{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration/1e6, 0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name IN ('SeatController.getLeftTicketOfInterval','POST /api/v1/seatservice/seats/left_tickets') GROUP BY 1,2", "claim": "Seat left_tickets and getLeftTicketOfInterval p95 rose to about 1,680 ms, versus about 10 ms in normal traces."},
        {"kind": "trace", "sql": "SELECT a.service_name AS caller_svc, b.service_name AS callee_svc, b.span_name, count(*) n, round(approx_quantile(b.duration/1e6,0.5),1) callee_p50, round(approx_quantile(a.duration/1e6,0.5),1) parent_p50 FROM abnormal_traces a JOIN abnormal_traces b ON a.trace_id=b.trace_id AND b.parent_span_id=a.span_id WHERE b.service_name='ts-seat-service' AND b.span_name LIKE '%left_tickets%' GROUP BY 1,2,3", "claim": "Seat's slow time is inside its own method: callers see the same ~1,680 ms with no database child spans."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration/1e6,0.5) p50_ms FROM normal_traces WHERE service_name='ts-seat-service' AND span_name='SeatController.getLeftTicketOfInterval' GROUP BY 1,2", "claim": "Normal-period baseline for seat getLeftTicketOfInterval is about 10 ms p95, so the abnormal 1,680 ms is a clear shift."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-seat-service", "to": "ts-travel2-service", "evidence": [{"kind": "trace", "sql": "SELECT a.service_name AS caller_svc, b.service_name AS callee_svc, count(*) n, round(approx_quantile(b.duration/1e6,0.5),1) callee_p50_ms, round(approx_quantile(a.duration/1e6,0.5),1) caller_p50_ms FROM abnormal_traces a JOIN abnormal_traces b ON a.trace_id=b.trace_id AND b.parent_span_id=a.span_id WHERE a.service_name='ts-travel2-service' AND b.service_name='ts-seat-service' GROUP BY 1,2", "claim": "Travel2 calls to seat take about 1,680 ms at p50, matching the seat slowdown."}]},
    {"from": "ts-seat-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT a.service_name AS caller_svc, b.service_name AS callee_svc, count(*) n, round(approx_quantile(b.duration/1e6,0.5),1) callee_p50_ms FROM abnormal_traces a JOIN abnormal_traces b ON a.trace_id=b.trace_id AND b.parent_span_id=a.span_id WHERE a.service_name='ts-travel-plan-service' AND b.service_name='ts-seat-service' GROUP BY 1,2", "claim": "Travel-plan's direct calls to seat take about 1,680 ms at p50."}]},
    {"from": "ts-seat-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration/1e6,0.5),1) p50_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name='TravelController.getTripAllDetailInfo' GROUP BY 1,2", "claim": "Travel getTripAllDetailInfo rises to about 3,387 ms p50, roughly two seat calls in sequence."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT a.service_name AS caller_svc, b.service_name AS callee_svc, count(*) n, round(approx_quantile(b.duration/1e6,0.5),1) callee_p50_ms, round(approx_quantile(a.duration/1e6,0.5),1) caller_p50_ms FROM abnormal_traces a JOIN abnormal_traces b ON a.trace_id=b.trace_id AND b.parent_span_id=a.span_id WHERE a.service_name='ts-route-plan-service' AND b.service_name='ts-travel2-service' GROUP BY 1,2", "claim": "Route-plan calls to travel2 slow sharply in the abnormal period, with travel2 tail latency driven by seat."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND span_name LIKE 'RoutePlanController.getCheapestRoutes' GROUP BY 1,2", "claim": "Route-plan getCheapestRoutes p95 rises to about 3,412 ms, which travel-plan inherits."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND span_name LIKE 'POST /api/v1/travelplanservice%' GROUP BY 1,2", "claim": "Travel-plan POST endpoints reach multi-second p95 (about 6.8 s on minStation and quickest) under the abnormal period."}]},
    {"from": "ts-travel-service", "to": "ts-preserve-service", "evidence": [{"kind": "trace", "sql": "SELECT a.service_name AS caller_svc, b.service_name AS callee_svc, count(*) n, round(approx_quantile(b.duration/1e6,0.5),1) callee_p50_ms, round(approx_quantile(a.duration/1e6,0.5),1) caller_p50_ms FROM abnormal_traces a JOIN abnormal_traces b ON a.trace_id=b.trace_id AND b.parent_span_id=a.span_id WHERE a.service_name='ts-preserve-service' AND b.service_name='ts-travel-service' GROUP BY 1,2", "claim": "Preserve's calls to travel take about 3,389 ms, carrying the seat delay upward."}]},
    {"from": "ts-preserve-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT a.service_name AS caller_svc, b.service_name AS callee_svc, count(*) n, round(approx_quantile(b.duration/1e6,0.5),1) callee_p50_ms, round(approx_quantile(a.duration/1e6,0.5),1) caller_p50_ms FROM abnormal_traces a JOIN abnormal_traces b ON a.trace_id=b.trace_id AND b.parent_span_id=a.span_id WHERE a.service_name='ts-ui-dashboard' AND b.service_name='ts-preserve-service' GROUP BY 1,2", "claim": "UI-dashboard calls to preserve take about 3,464 ms p50, so users see the delay on preserve requests."}]}
  ]
}

